/* TransferOS-China 客服组件：FAQ 机器人 + 转人工（邮箱 info@zhuanuc.com；微信配置保留停用）——纯前端，零后端 */
"use strict";

var CHAT_CONFIG = {
  email: "info@zhuanuc.com",     /* 人工客服邮箱（2026-10-22 起为唯一人工通道） */
  wechatId: "一笑一尘缘",       /* 客服微信昵称（停用保留） */
  wechatQr: "data:image/jpeg;base64,", /* 客服微信二维码图片路径 */
  botName: "TransferOS 小助手",
  /* 管理后台 API 地址：部署完成后填入（留空 = 只用本地问答库） */
  apiBase: "https://transferos-admin.szzxli711.workers.dev"
};

var CHAT_FAQ = [];
var CHAT_READY = false;

function chatInit() {
  var root = document.getElementById("chatRoot");
  if (!root) return;
  root.innerHTML =
    '<button id="chatFab" aria-label="客服">💬</button>' +
    '<div id="chatPanel" hidden>' +
    '  <div class="chat-head"><b>🤖 ' + esc(CHAT_CONFIG.botName) + '</b>' +
    '  <span><button id="chatHuman" class="chat-link">转人工</button>' +
    '  <button id="chatClose" class="chat-link">✕</button></span></div>' +
    '  <div id="chatMsgs" class="chat-msgs"></div>' +
    '  <div id="chatChips" class="chat-chips"></div>' +
    '  <div class="chat-input"><input id="chatText" type="text" placeholder="输入问题…" autocomplete="off">' +
    '  <button id="chatSend">发送</button></div>' +
    '</div>';
  document.getElementById("chatFab").addEventListener("click", chatToggle);
  document.getElementById("chatClose").addEventListener("click", chatToggle);
  document.getElementById("chatHuman").addEventListener("click", function () { chatHumanCard(); });
  document.getElementById("chatSend").addEventListener("click", chatSend);
  document.getElementById("chatText").addEventListener("keydown", function (e) {
    if (e.key === "Enter") chatSend();
  });
  var _lang = "zh-CN";
  try { _lang = localStorage.getItem("tog_lang") || "zh-CN"; } catch (e) {}
  var _faqFile = _lang === "en" ? "data/faq-en.json?v=1" : _lang === "zh-TW" ? "data/faq-tw.json?v=1" : "data/faq.json?v=1";
  var _greet = _lang === "en" ? "Hello" : _lang === "zh-TW" ? "你好" : "你好";
  var _chips = _lang === "en"
    ? ["How are costs calculated", "Which schools", "What is TAG", "Visa risks", "Materials needed"]
    : _lang === "zh-TW"
    ? ["費用怎麼算？", "哪些學校能上？", "TAG是什麼？", "簽證有風險嗎？", "申請要什麼材料？"]
    : ["费用怎么算？", "哪些学校能上？", "TAG是什么？", "签证有风险吗？", "申请要什么材料？"];
  function _useFaq(j) {
    CHAT_FAQ = j; CHAT_READY = true;
    var g = faqFind(_greet);
    chatBotSay(g ? g.a : "");
    chatChips(_chips);
  }
  function _loadLocal() {
    fetch(_faqFile).then(function (r) { return r.json(); }).then(_useFaq).catch(function () {
      chatBotSay(_lang === "en" ? "Knowledge base failed to load. Retry later or talk to a human." : "知识库加载失败，请稍后重试，或直接转人工。");
    });
  }
  function _apiKeys(q) {
    var clean = String(q || "").replace(/[？?！!。．·、,，:：;；""''「」()（）]/g, " ");
    var parts = clean.split(/\s+/).filter(function (s) { return s.length >= 2; });
    var seen = {}, keys = [];
    function add(k) { if (k && !seen[k]) { seen[k] = 1; keys.push(k); } }
    parts.forEach(add);
    var whole = clean.replace(/\s+/g, "");
    if (whole.length >= 2) add(whole);
    for (var i = 0; i + 1 < whole.length && keys.length < 14; i++) add(whole.substr(i, 2));
    return keys.slice(0, 14);
  }
  if (CHAT_CONFIG.apiBase) {
    fetch(CHAT_CONFIG.apiBase + "/api/faq?lang=" + encodeURIComponent(_lang))
      .then(function (r) { if (!r.ok) throw new Error("api"); return r.json(); })
      .then(function (rows) {
        if (!rows || !rows.length) throw new Error("empty");
        _useFaq(rows.map(function (f) { return { q: f.q, a: f.a, keys: _apiKeys(f.q) }; }));
      })
      .catch(function () { _loadLocal(); });
  } else {
    _loadLocal();
  }
}

/* ---- 纯逻辑：可在 node 里单元测试 ---- */
function faqScore(entry, msg) {
  var m = msg.toLowerCase(), s = 0;
  (entry.keys || []).forEach(function (k) {
    if (k && m.indexOf(String(k).toLowerCase()) >= 0) s++;
  });
  return s;
}
function faqFind(msg) {
  var best = null, bestScore = 0;
  CHAT_FAQ.forEach(function (e) {
    var s = faqScore(e, msg);
    if (s > bestScore) { bestScore = s; best = e; }
  });
  return bestScore > 0 ? best : null;
}
function humanCardHTML(note) {
  var subj = encodeURIComponent(note || "TransferOS咨询");
  return '<div class="human-card"><b>👩‍💼 人工客服（邮件）</b>' +
    '<p>写邮件给我们：<b>' + esc(CHAT_CONFIG.email) + '</b></p>' +
    '<p><a class="btn" href="mailto:' + esc(CHAT_CONFIG.email) + '?subject=' + subj + '">✉️ 点这里写邮件</a> <button type="button" class="mini-btn" onclick="if(navigator.clipboard){navigator.clipboard.writeText(\'' + esc(CHAT_CONFIG.email) + '\');}this.textContent=\'已复制 ✓\'">复制邮箱</button></p>' +
    '<p class="hint">邮件主题已带好备注（' + esc(note || "TransferOS咨询") + '），正文写下你的问题即可。如果点按钮没反应，就复制邮箱手动发，主题写上面这行备注。</p></div>';
}
if (typeof module !== "undefined") { module.exports = { faqScore: faqScore, faqFind: faqFind, humanCardHTML: humanCardHTML }; }

/* ---- 页面交互 ---- */
function chatToggle() {
  var p = document.getElementById("chatPanel");
  p.hidden = !p.hidden;
}
function chatScroll() {
  var m = document.getElementById("chatMsgs");
  m.scrollTop = m.scrollHeight;
}
function chatBotSay(html) {
  var m = document.getElementById("chatMsgs");
  var d = document.createElement("div");
  d.className = "msg bot";
  d.innerHTML = html;
  m.appendChild(d);
  chatScroll();
}
function chatUserSay(t) {
  var m = document.getElementById("chatMsgs");
  var d = document.createElement("div");
  d.className = "msg user";
  d.textContent = t;
  m.appendChild(d);
  chatScroll();
}
function chatChips(list) {
  var c = document.getElementById("chatChips");
  c.innerHTML = "";
  list.forEach(function (t) {
    var b = document.createElement("button");
    b.className = "chip";
    b.textContent = t;
    b.addEventListener("click", function () { chatAsk(t); });
    c.appendChild(b);
  });
}
function chatAsk(text) {
  chatUserSay(text);
  document.getElementById("chatText").value = "";
  setTimeout(function () {
    var hit = faqFind(text);
    if (hit && hit.a === "__HUMAN__") { chatHumanCard(); return; }
    if (hit) { chatBotSay(esc(hit.a)); return; }
    chatBotSay("这个问题我答不上来，为你转人工客服 👇");
    chatHumanCard();
  }, 350);
}
function chatSend() {
  var t = document.getElementById("chatText").value.trim();
  if (!t) return;
  chatAsk(t);
}
function chatHumanCard(note) {
  var m = document.getElementById("chatMsgs");
  if (m) {
    var existing = m.querySelector(".human-card");
    if (existing) { if (existing.scrollIntoView) existing.scrollIntoView({ behavior: "smooth", block: "nearest" }); return; }
  }
  chatBotSay(humanCardHTML(note));
}
document.addEventListener("DOMContentLoaded", chatInit);
